INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p513572-mkt345', 'stk-blue_monaro', 'MKT 345', 'info', '{"desc": "ابعدددددددددددد عن هالكورس\nتراه غثييييث وكله شغل\nالدكتور ما عليه كلام بس الكورس … من اصعب الكورسات اللي درستها ومن اغث الكورسات\nياخي عندك الكتف ثانيه\nبعد اطلاعي على كورسات الترم 092\n330 كوورس مررره حلوووو ووممتع جدا … بس للاسف الدكتور حقه ما اعرفه واسمه اول مره يمر علي … وانا اخذته مع صالح الشبل\n\n340 … نفس الشي كورس مره حلو وومتع … بس للاسف الدكتور مروان كنت اسمع به بس ما درست عنده اي كورس … وانا اخذت ال340 مع روبرت ابوكو … نفس الدكتور اللي بيدرس ال345 هالسمستر\n\n400… هههههههههههه مع حسين العمري كالعاده … هالدكتور فنان … ورهيب … بس اسألته صعبه شوي … واحيانا يعصب … الكورس فيه اكثر من برزنتيشن … انا اخذت الكورس وسويت تقريبا 4 او5 برزنتشن وفيها دسكشن وقلق … وفيها 2 ديبيت … يقسم الكلاس لنصفين ويسوي ديبيت على موضوع معين… بس في النهايه يدف الطلاب كلهم ويعطيك اكثر من حقك … انت وضميرك … ودي اقول لك خذ عنده … بس اخاف بعدين تدعي علي هههههههههه\n\n410 … مع محمد سعدي … هالدكتور ما عرفت له … اخذت عنده ال42- في الصيف وعطاني دي بلس … واخذت عنده الـ410 في 082 وعطاني بي بلس … مع اني باذل نفس المجهود\nانا ما حبيت هالدكتور الصراحه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-345/81096/4", "user": "Blue_Monaro", "ts": 1262358392000, "tid": 81096, "pn": 4}}', 1262358392000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
